class FoundrySettings {
  constructor(workerEnergy, orderCount) {
    this.workerEnergy = workerEnergy;
    this.orderCount = orderCount;
  }

  summary() {
    return `Worker energy: ${this.workerEnergy}, orders queued: ${this.orderCount}`;
  }
}

const settings = new FoundrySettings(10, 4);
console.log(settings.summary());

